//! URL shaping, containment and naming. //! //! [`ensure_trailing_slash`] is what makes [`is_under_base`]'s prefix test a //! statement about directories rather than about strings, so the two belong //! together. use reqwest::Url; use crate::engine; use super::path::sanitize_path_component; pub(super) fn ensure_trailing_slash(mut url: Url) -> Url { url.set_fragment(None); if !url.path().ends_with('/') { let new_path = format!("{}/", url.path()); url.set_path(&new_path); } url } pub(super) fn is_under_base(url: &Url, base: &Url) -> bool { if url.scheme() != base.scheme() { return false; } if url.host_str() != base.host_str() { return false; } if url.port_or_known_default() != base.port_or_known_default() { return false; } // base.path() ends with '/' by construction. url.path().starts_with(base.path()) } pub(super) fn derive_folder_name(base: &Url) -> String { let path = base.path().trim_end_matches('/'); let last = path.rsplit('/').next().unwrap_or(""); let candidate = if last.is_empty() { base.host_str().unwrap_or("download").to_owned() } else { engine::percent_decode(last) }; sanitize_path_component(&candidate).unwrap_or_else(|| "download".to_owned()) } pub(super) fn directory_label(base: &Url, dir: &Url) -> String { let rel = dir .as_str() .strip_prefix(base.as_str()) .unwrap_or(dir.as_str()); let decoded = engine::percent_decode(rel); let trimmed = decoded.trim_end_matches('/'); let last = trimmed.rsplit('/').next().unwrap_or(""); if last.is_empty() { dir.as_str().to_owned() } else { last.to_owned() } } // ---------- Tests ---------- #[cfg(test)] mod tests { use super::*; fn u(s: &str) -> Url { Url::parse(s).unwrap() } #[test] fn test_ensure_trailing_slash() { assert_eq!( ensure_trailing_slash(u("http://x.com/dir")).as_str(), "http://x.com/dir/" ); assert_eq!( ensure_trailing_slash(u("http://x.com/dir/")).as_str(), "http://x.com/dir/" ); // Query is preserved (unlike old behavior). assert_eq!( ensure_trailing_slash(u("http://x.com/dir?q=1")).as_str(), "http://x.com/dir/?q=1" ); // Fragment is dropped. assert_eq!( ensure_trailing_slash(u("http://x.com/dir#frag")).as_str(), "http://x.com/dir/" ); } #[test] fn test_is_under_base() { let base = ensure_trailing_slash(u("http://x.com/files/")); assert!(is_under_base(&u("http://x.com/files/a.zip"), &base)); assert!(is_under_base(&u("http://x.com/files/sub/a.zip"), &base)); assert!(!is_under_base(&u("http://x.com/other/a.zip"), &base)); assert!(!is_under_base(&u("https://x.com/files/a.zip"), &base)); // scheme differs assert!(!is_under_base(&u("http://y.com/files/a.zip"), &base)); // host differs } }
